PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR

IF EStop = FALSE THEN
    Motor := FALSE;
ELSIF Start AND NOT Stop THEN
    Motor := TRUE;
ELSIF Stop THEN
    Motor := FALSE;
ELSE
    Motor := Motor; // Hold current state if neither Start nor Stop
END_IF;

END_PROGRAM

