PROGRAM alarm_ctrl
VAR_INPUT
    Trip : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Alarm : BOOL;
END_VAR
VAR
    Alarm_Latched : BOOL := FALSE;
END_VAR

IF Trip THEN
    Alarm_Latched := TRUE;
ELSIF Reset AND NOT Trip THEN
    Alarm_Latched := FALSE;
END_IF;

Alarm := Alarm_Latched;
END_PROGRAM

