        TEW_R(IN := TRUE, PT := T#1s);
    3 :
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
        TNS_R(IN := TRUE, PT := T#1s);
        TEW_G(IN := TRUE, PT := T#2s);
    4 :
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
        TNS_R(IN := TRUE, PT := T#1s);
        TEW_G(IN := TRUE, PT := T#2s);
    5 :
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        TNS_R(IN := TRUE, PT := T#1s);
        TEW_G(IN := TRUE, PT := T#1s);
END_CASE;

IF TNS_G.Q AND NOT TNS_Y.Q AND NOT TNS_R.Q THEN
    State := 0;
ELSIF TNS_Y.Q AND NOT TNS_G.Q AND NOT TNS_R.Q THEN
    State := 1;
ELSIF TNS_R.Q AND NOT TNS_G.Q AND NOT TNS_Y.Q THEN
    State := 2;
ELSIF TEW_G.Q AND NOT TEW_Y.Q AND NOT TEW_R.Q THEN
    State := 3;
ELSIF TEW_Y.Q AND NOT TEW_G.Q AND NOT TEW_R.Q THEN
    State := 4;
ELSIF TEW_R.Q AND NOT TEW_G.Q AND NOT TEW_Y.Q THEN
    State := 5;
END_IF;
END_PROGRAM

