PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0: // Idle
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;

    1: // Fill
        IF NOT EStop AND Level >= 80 THEN
            State := 2;
        END_IF;
        FillValve := EStop AND (NOT EStop OR Level < 80);

    2: // Heat
        IF NOT EStop AND Temp >= 100 THEN
            State := 3;
        END_IF;
        Heater := EStop AND (NOT EStop OR Temp < 100);
        Agitator := EStop AND (NOT EStop OR Temp < 100);

    3: // React
        IF NOT EStop THEN
            State := 4;
        END_IF;
        Heater := EStop AND (NOT EStop OR Temp < 100);
        Agitator := EStop AND (NOT EStop OR Temp < 100);

    4: // Drain
        IF NOT EStop AND Level <= 5 THEN
            State := 0;
        END_IF;
        DrainValve := EStop AND (NOT EStop OR Level > 5);
END_CASE

// Safety conditions
FillValve := EStop AND (NOT EStop OR (NOT FillValve OR NOT DrainValve));
DrainValve := EStop AND (NOT EStop OR (NOT FillValve OR NOT DrainValve));
Heater := EStop AND (NOT EStop OR Level >= 10);
Agitator := EStop AND (NOT EStop OR Level >= 10);
END_PROGRAM

