    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0:  // Idle
            IF Level < LVL_HIGH THEN
                State := 1;
            END_IF;

        1:  // Fill
            IF Level >= LVL_HIGH THEN
                State := 2;
            ELSE
                FillValve := TRUE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;

        2:  // Heat
            IF Level >= LIQ_MIN AND Temp >= TEMP_SET THEN
                State := 3;
            ELSE
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;

        3:  // React
            IF Time > PT_REACT THEN
                State := 4;
            ELSE
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;

        4:  // Drain
            IF Level <= LVL_LOW THEN
                State := 0;
            ELSE
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

// Safety conditions
IF FillValve AND DrainValve OR Level < LIQ_MIN AND (Heater OR Agitator) THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
