        1: // Fill
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            IF Level >= LVL_HIGH THEN
                State := 2;
            END_IF;
        2: // Heat
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
