            IF NOT TON_1.Q THEN
                State := 4;
            END_IF;
        4: // Drain
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

// Safety conditions
