        Agitator := EStop;
        DrainValve := FALSE;

    4: // Drain
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
        END_IF;
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := EStop AND Level > LVL_LOW;
END_CASE;

