            State := 1;
        END_IF;
        C1 := FALSE;
        C2 := FALSE;
    1:
        IF EStop OR StopPB THEN
            State := 0;
        ELSIF PT_SEQ <= T#0s THEN
            State := 2;
        END_IF;
        C1 := FALSE;
        C2 := TRUE;
    2:
        IF EStop OR StopPB THEN
            State := 0;
        END_IF;
        C1 := TRUE;
        C2 := TRUE;
END_CASE;

