    State := 2;
    C1 := TRUE;
    C2 := TRUE;
ELSIF (NOT StartPB) AND (State = 2) THEN
    State := 1;
    C1 := FALSE;
    C2 := TRUE;
ELSIF NOT PT_SEQ.Q AND (State = 2) THEN
    State := 1;
    C1 := FALSE;
    C2 := TRUE;
END_IF;

CASE State OF
    0: 
        C1 := FALSE;
        C2 := FALSE;
    1: 
        C1 := FALSE;
        C2 := TRUE;
    2: 
        C1 := TRUE;
        C2 := TRUE;
END_CASE;

PT_SEQ(IN := TRUE, PT := T#2s);
