PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
    T1 : TON;
    T2 : TON;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND NOT StopPB THEN
                State := 1;
            END_IF;
        1:
            IF T1.Q THEN
                State := 2;
            END_IF;
        2:
            IF T2.Q THEN
                State := 3;
            END_IF;
        3:
            IF StopPB OR NOT EStop THEN
                State := 0;
            END_IF;
    END_CASE;

    T1(IN := TRUE, PT := T#2s);
    T2(IN := TRUE, PT := T#2s);

    C1 := State >= 3;
    C2 := State >= 2;
    C3 := State >= 1;
ELSE
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
ELSIF StartPB AND State = 0 THEN
    State := 1;
ELSIF State = 1 AND T#2s > PT_SEQ THEN
    State := 2;
ELSIF State = 2 AND T#4s > 2 * PT_SEQ THEN
    State := 3;
END_IF;

CASE State OF
    0: C1 := FALSE; C2 := FALSE; C3 := FALSE;
    1: C1 := FALSE; C2 := FALSE; C3 := TRUE;
    2: C1 := FALSE; C2 := TRUE; C3 := TRUE;
    3: C1 := TRUE; C2 := TRUE; C3 := TRUE;
END_CASE;

