    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
    SeqTimer1 : TON;
    SeqTimer2 : TON;
END_VAR

SeqTimer1(IN := NOT EStop AND NOT StopPB AND (State = 0 OR State = 1), PT := T#2s);
SeqTimer2(IN := NOT EStop AND NOT StopPB AND (State = 1 OR State = 2), PT := T#2s);

CASE State OF
    0:
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;
    1:
        IF SeqTimer1.Q THEN
            C3 := TRUE;
            State := 2;
        END_IF;
    2:
        IF SeqTimer2.Q THEN
            C2 := TRUE;
            State := 3;
        END_IF;
    3:
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

IF State >= 1 THEN
    C3 := TRUE;
END_IF;
IF State >= 2 THEN
    C2 := TRUE;
END_IF;
IF State = 3 THEN
    C1 := TRUE;
END_IF;

END_PROGRAM

