        C3 := TRUE;
        IF NOT EStop AND NOT StopPB AND State = 1 AND NOT C2 THEN
            State := 2;
        END_IF;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        IF NOT EStop AND NOT StopPB AND State = 2 AND NOT C3 THEN
            State := 3;
        END_IF;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
        IF NOT EStop OR StopPB THEN
            State := 0;
        END_IF;
END_CASE;

IF NOT EStop OR StopPB THEN
    State := 0;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
    T_C3 : TON;
    T_C2 : TON;
END_VAR

CASE State OF
    0:
        IF StartPB AND EStop THEN
            State := 1;
            T_C3(IN := TRUE, PT := T#2s);
        END_IF;
    1:
        IF NOT T_C3.Q OR StopPB OR NOT EStop THEN
            State := 0;
        ELSIF T_C3.Q AND StartPB AND EStop THEN
            State := 2;
            T_C2(IN := TRUE, PT := T#2s);
        END_IF;
    2:
        IF NOT T_C2.Q OR StopPB OR NOT EStop THEN
            State := 1;
        ELSIF T_C2.Q AND StartPB AND EStop THEN
            State := 3;
            T_C1(IN := TRUE, PT := T#2s);
        END_IF;
    3:
        IF NOT T_C1.Q OR StopPB OR NOT EStop THEN
            State := 2;
        END_IF;
END_CASE;

C1 := (State >= 3) AND EStop;
C2 := (State >= 2) AND EStop;
C3 := (State >= 1) AND EStop;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
    T1 : TON;
    T2 : TON;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
    T1(IN := FALSE);
    T2(IN := FALSE);
ELSIF StartPB AND State = 0 THEN
    State := 1;
    T1(IN := TRUE, PT := T#2s);
    T2(IN := FALSE);
ELSIF T1.Q AND State = 1 THEN
    State := 2;
    T2(IN := TRUE, PT := T#2s);
ELSIF T2.Q AND State = 2 THEN
    State := 3;
    T1(IN := FALSE);
    T2(IN := FALSE);
END_IF;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
END_CASE;

END_PROGRAM

